equals:
@and(
  not(empty(body('Read_participant')?['Participantaccount']?['Claims'])),
  equals(
    body('Read_response_revision')?['d']?['RecipientParticipantId'],
    body('Read_participant')?['ID']
  ),
  equals(
    body('Read_response_revision')?['d']?['SenderParticipantId'],
    body('Read_request')?['SenderParticipantId']
  ),
  equals(
    body('Read_response_revision')?['d']?['RecipientParticipantId'],
    body('Read_request')?['RecipientParticipantId']
  ),
  equals(
    body('Read_response_revision')?['d']?['Status'],
    'Pending'
  ),
  or(
    equals(outputs('Requested_decision'), 'Accept'),
    equals(outputs('Requested_decision'), 'Decline')
  )
)

Compatible_languages.inputs:
@union(
  intersection(
    coalesce(body('Read_sender')?['Teachlanguages#Id'], json('[]')),
    coalesce(body('Read_participant')?['Learnlanguages#Id'], json('[]'))
  ),
  intersection(
    coalesce(body('Read_sender')?['Learnlanguages#Id'], json('[]')),
    coalesce(body('Read_participant')?['Teachlanguages#Id'], json('[]'))
  )
)

Compatible_cultures.inputs:
@union(
  intersection(
    coalesce(body('Read_sender')?['ShareCultures#Id'], json('[]')),
    coalesce(body('Read_participant')?['LearnCultures#Id'], json('[]'))
  ),
  intersection(
    coalesce(body('Read_sender')?['LearnCultures#Id'], json('[]')),
    coalesce(body('Read_participant')?['ShareCultures#Id'], json('[]'))
  )
)

inputs.where:
@equals(and(
  equals(
    item()?['Participant']?['Id'],
    body('Read_request')?['SenderParticipantId']
  ),
  equals(
    item()?['MembershipKey'],
    concat(
      'request:',
      string(body('Read_request')?['ID']),
      ':participant:',
      string(body('Read_request')?['SenderParticipantId'])
    )
  )
),true)

@equals(and(
  equals(
    item()?['Participant']?['Id'],
    body('Read_request')?['RecipientParticipantId']
  ),
  equals(
    item()?['MembershipKey'],
    concat(
      'request:',
      string(body('Read_request')?['ID']),
      ':participant:',
      string(body('Read_request')?['RecipientParticipantId'])
    )
  )
),true)

equals:
@and(
  equals(body('Read_group_revision')?['d']?['SetupComplete'], false),
  equals(
    body('Read_group_revision')?['d']?['SourceRequestId'],
    body('Read_request')?['ID']
  ),
  equals(body('Read_group_revision')?['d']?['State'], 'Closed'),
  contains(
    createArray(2, 3, 4, 5, 6, 7, 8, 9, 10),
    body('Read_group_revision')?['d']?['Capacity']
  ),
  or(
    and(
      equals(
        body('Read_group_revision')?['d']?['ExchangeType'],
        'Language'
      ),
      contains(
        createArray(2, 3),
        body('Read_group_revision')?['d']?['Capacity']
      )
    ),
    contains(
      createArray('Culture', 'Combined'),
      body('Read_group_revision')?['d']?['ExchangeType']
    )
  )
)

inputs.value:
@if(
  contains(
    createArray('Cancelled', 'Declined'),
    body('Read_cleanup_request')?['d']?['Status']
  ),
  concat(
    'The request is ',
    toLower(body('Read_cleanup_request')?['d']?['Status']),
    '. This acceptance did not complete.'
  ),
  'Group setup has not completed. Please check My requests.'
)

equals:
@and(
  equals(
    body('Read_cleanup_membership_revision')?['d']?['MembershipStatus'],
    'Active'
  ),
  equals(
    body('Read_cleanup_membership_revision')?['d']?['GroupId'],
    variables('ResultGroupId')
  ),
  contains(
    createArray(
      body('Read_request')?['SenderParticipantId'],
      body('Read_request')?['RecipientParticipantId']
    ),
    body('Read_cleanup_membership_revision')?['d']?['ParticipantId']
  ),
  equals(
    body('Read_cleanup_membership_revision')?['d']?['MembershipKey'],
    concat(
      'request:',
      string(body('Read_request')?['ID']),
      ':participant:',
      string(body('Read_cleanup_membership_revision')?['d']?['ParticipantId'])
    )
  )
)

@and(
  equals(
    body('Read_cleanup_group')?['d']?['SetupComplete'],
    false
  ),
  equals(
    body('Read_cleanup_group')?['d']?['SourceRequestId'],
    body('Read_request')?['ID']
  ),
  contains(
    createArray('Closed', 'Ended'),
    body('Read_cleanup_group')?['d']?['State']
  )
)
